WITH scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at DESC, id) AS event_seq, ROW_NUMBER() OVER w_grp AS seq_no, LAST_VALUE(country, TRUE) OVER (PARTITION BY device, customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, LAST_VALUE(country) IGNORE NULLS OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country_2, ROW_NUMBER() OVER (ORDER BY started_at, id) AS event_seq_2 FROM sessions WINDOW w_grp AS (PARTITION BY browser ORDER BY started_at, id)) SELECT device, CASE WHEN seq_no >= 7 THEN 'LARGE' ELSE 'SMALL' END AS seq_no_tier, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, COUNT(*) AS row_count, APPROX_PERCENTILE(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles FROM scored GROUP BY device, CASE WHEN seq_no >= 7 THEN 'LARGE' ELSE 'SMALL' END HAVING (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 > 0;
